//! Per-build translation of the macOS 1.19.4.1 addresses the management tools
//! use (`launch/macos`).
//!
//! Tools keep the macOS (Mach-O DFA875A5, libc++) values as their canonical
//! keys and resolve them through [`img`] (image-relative vtables and globals)
//! and [`fld`] (struct field offsets of an owning class). On macOS both return
//! the key unchanged. On Linux (libstdc++) they read the table generated by
//! `scripts/cross_platform_map.py` for the verified ELF build; an entry that
//! is absent fails with `layout_unmapped`, so a tool never reads or clicks from
//! a guessed address.
use crate::{
    error::{Error, Result},
    memory::StringAbi,
};
use std::{collections::HashMap, sync::OnceLock};

/// The class that owns a field: its RTTI name and macOS image-relative vtable
/// (0 when it has none; such fields are mapped through an anchor function).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) struct Class {
    pub name: &'static str,
    pub vtable: u64,
}
impl Class {
    pub(crate) const fn new(name: &'static str, vtable: u64) -> Self {
        Self { name, vtable }
    }
}

/// One generated build table.
#[derive(Default, Debug)]
pub(crate) struct Table {
    /// GNU build ID of the ELF the table was generated for; the Linux server
    /// compares it with the running game before registering tools.
    #[cfg_attr(not(target_os = "linux"), allow(dead_code))]
    pub build_id: String,
    image: HashMap<u64, u64>,
    fields: HashMap<(String, u64), u64>,
}

fn hex(s: &str) -> Option<u64> {
    u64::from_str_radix(s.strip_prefix("0x")?, 16).ok()
}

impl Table {
    /// Parse the generated JSON: {"build_id", "image": {mac: elf},
    /// "fields": {class: {mac: elf}}} with hexadecimal strings.
    pub(crate) fn parse(text: &str) -> Result<Self> {
        let bad = |m: &str| Error::new("layout_invalid", m.to_string());
        let v: serde_json::Value = serde_json::from_str(text).map_err(|e| bad(&e.to_string()))?;
        let mut table = Table {
            build_id: v["build_id"]
                .as_str()
                .ok_or_else(|| bad("build_id missing"))?
                .to_string(),
            ..Default::default()
        };
        for (k, val) in v["image"].as_object().into_iter().flatten() {
            let (Some(a), Some(b)) = (hex(k), val.as_str().and_then(hex)) else {
                return Err(bad("image entry not hexadecimal"));
            };
            table.image.insert(a, b);
        }
        for (class, map) in v["fields"].as_object().into_iter().flatten() {
            for (k, val) in map.as_object().into_iter().flatten() {
                let (Some(a), Some(b)) = (hex(k), val.as_str().and_then(hex)) else {
                    return Err(bad("field entry not hexadecimal"));
                };
                table.fields.insert((class.clone(), a), b);
            }
        }
        Ok(table)
    }
    fn image(&self, mac: u64) -> Result<u64> {
        self.image.get(&mac).copied().ok_or_else(|| {
            Error::new(
                "layout_unmapped",
                format!("Address 0x{mac:x} is not mapped for this Linux build"),
            )
        })
    }
    fn field(&self, class: &Class, mac: u64) -> Result<u64> {
        self.fields
            .get(&(class.name.to_string(), mac))
            .copied()
            .ok_or_else(|| {
                Error::new(
                    "layout_unmapped",
                    format!(
                        "Field {}+0x{mac:x} is not mapped for this Linux build",
                        class.name
                    ),
                )
            })
    }
}

/// Generated table for the Linux build, when one is shipped.
const LINUX_TABLE: Option<&str> = None;

fn linux() -> Result<&'static Table> {
    static TABLE: OnceLock<std::result::Result<Table, String>> = OnceLock::new();
    TABLE
        .get_or_init(|| match LINUX_TABLE {
            None => Err("No verified Linux layout ships for the management tools".into()),
            Some(text) => Table::parse(text).map_err(|e| e.message),
        })
        .as_ref()
        .map_err(|m| Error::new("layout_unmapped", m.clone()))
}

/// The management tools may bind on Linux: a generated table ships and was
/// made for exactly the running build.
#[cfg(target_os = "linux")]
pub(crate) fn require_linux(build_id: &str) -> Result<()> {
    let table = linux()?;
    if table.build_id != build_id {
        return Err(Error::new(
            "layout_unmapped",
            format!(
                "The Linux layout is for build {}, the game is {build_id}",
                table.build_id
            ),
        ));
    }
    Ok(())
}

/// Image-relative address (vtable, global) for this build.
pub(crate) fn img(abi: StringAbi, mac: u64) -> Result<u64> {
    match abi {
        StringAbi::LibCxx => Ok(mac),
        StringAbi::LibStdCxx => linux()?.image(mac),
    }
}

/// Field offset in `class` for this build.
pub(crate) fn fld(abi: StringAbi, class: &Class, mac: u64) -> Result<u64> {
    match abi {
        StringAbi::LibCxx => Ok(mac),
        StringAbi::LibStdCxx => linux()?.field(class, mac),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    const VIEW: Class = Class::new("CCountryPoliticsView", 0x36511f0);

    #[test]
    fn macos_values_are_the_keys() {
        assert_eq!(img(StringAbi::LibCxx, 0x36511f0).unwrap(), 0x36511f0);
        assert_eq!(fld(StringAbi::LibCxx, &VIEW, 0x3958).unwrap(), 0x3958);
    }

    #[test]
    fn linux_without_a_table_refuses() {
        let e = img(StringAbi::LibStdCxx, 0x36511f0).unwrap_err();
        assert_eq!(e.code, "layout_unmapped");
        let e = fld(StringAbi::LibStdCxx, &VIEW, 0x3958).unwrap_err();
        assert_eq!(e.code, "layout_unmapped");
    }

    #[test]
    fn generated_table_lookups() {
        let t = Table::parse(
            r#"{"build_id":"x","image":{"0x36511f0":"0x4211000"},
                "fields":{"CCountryPoliticsView":{"0x3958":"0x3b10"}}}"#,
        )
        .unwrap();
        assert_eq!(t.image(0x36511f0).unwrap(), 0x4211000);
        assert_eq!(t.field(&VIEW, 0x3958).unwrap(), 0x3b10);
        assert_eq!(t.field(&VIEW, 0x50).unwrap_err().code, "layout_unmapped");
        assert!(Table::parse(r#"{"build_id":"x","image":{"12":"0x1"}}"#).is_err());
    }
}
